if (input.cmd === "checkout") {
  const cart = createCart();
  for (const item of input.items ?? []) {
    addItem(cart, item.sku, item.price, item.qty ?? 1);
  }
  const couponResult = input.coupon ? applyCoupon(cart, input.coupon) : null;
  emit({
    cmd: "checkout",
    coupon: cart.coupon,
    couponResult,
    totals: cart.totals,
    saved: serialize(cart),
  });

export function applyCoupon(cart, code) {
  const rule = COUPONS[code];
  if (!rule) {
    return { ok: false, reason: "unknown coupon" };
  }
  const subtotal = cart.totals.subtotal;
  let discount;
  if (rule.kind === "fixed") {
    discount = rule.value;
  } else {
    discount = Math.min(round2((subtotal * rule.value) / 100), rule.cap);
  }
  discount = round2(Math.min(discount, subtotal));
  cart.coupon = code;
  cart.totals.discount = discount;
  cart.totals.total = round2(subtotal - discount);
  return { ok: true, code, discount, total: cart.totals.total };
}

export function serialize(cart) {
  return { items: cart.items, coupon: cart.coupon };
}

export function reload(saved) {
  const cart = {
    items: Array.isArray(saved.items) ? saved.items : [],
    coupon: saved.coupon ?? null,
    totals: { subtotal: 0, discount: 0, total: 0 },
  };
  recompute(cart);
  return cart;
}

export function recompute(cart) {
  const subtotal = cart.items.reduce((sum, item) => sum + item.price * item.qty, 0);
  cart.totals.subtotal = round2(subtotal);
  cart.totals.discount = 0;
  cart.totals.total = round2(subtotal);
}
